OUT=(Path(__file__).resolve().parents[1]/'test-results');results=[]; (Path(__file__).resolve().parents[1]/'test-results').mkdir(exist_ok=True);errors=[]
def check(name,condition,detail=None):
    results.append({'test':name,'passed':bool(condition),'detail':detail})
    print(('PASS ' if condition else 'FAIL ')+name,detail or '',flush=True)
    (OUT/'flows.json').write_text(json.dumps(results,ensure_ascii=False,indent=2))
    if not condition: raise AssertionError(name+': '+str(detail))
def approx(a,b):return abs(a-b)<.025
